import unittest


def sort_array(arr):
    return sorted(sorted(arr), key=lambda x: bin(x)[2:].count('1'))


class TestSortArray(unittest.TestCase):

    def test_example_case(self):
        self.assertEqual(sort_array([1, 5, 2, 3, 4]), [1, 2, 4, 3, 5])

    def test_negative_numbers(self):
        self.assertEqual(sort_array([-2, -3, -4, -5, -6]), [-6, -5, -4, -3, -2])

    def test_empty_array(self):
        self.assertEqual(sort_array([]), [])

    def test_single_element(self):
        self.assertEqual(sort_array([7]), [7])

    def test_with_zero(self):
        self.assertEqual(sort_array([1, 0, 2, 3, 4]), [0, 1, 2, 4, 3])

    def test_already_sorted_by_bits(self):
        self.assertEqual(sort_array([1, 2, 4, 8]), [1, 2, 4, 8])

    def test_duplicates(self):
        self.assertEqual(sort_array([3, 3, 1, 1]), [1, 1, 3, 3])

    def test_all_same_bit_count(self):
        # 1, 2, 4, 8 all have one bit set; ties broken by ascending value
        self.assertEqual(sort_array([8, 4, 2, 1]), [1, 2, 4, 8])

    def test_power_of_two_and_three(self):
        # 2 has one '1' bit, 3 has two '1' bits
        self.assertEqual(sort_array([3, 2]), [2, 3])

    def test_does_not_modify_original(self):
        arr = [3, 1, 2]
        sort_array(arr)
        self.assertEqual(arr, [3, 1, 2])


if __name__ == "__main__":
    unittest.main()
```

